    {
      auto& p = bodies.fst;
      e += 0.5 * p.mass * (p.vx * p.vx + p.vy * p.vy + p.vz * p.vz);

      foreach_block<decltype(bodies)> run = {bodies,e};
      FOREACH(run,bodies.snd);
    }
  };

  template<class T> double operator()(T& bodies)
  {
    double e = 0.0;
    for_block run = {e};
    FOR(run,bodies);
