/* The Computer Language Benchmarks Game
   https://salsa.debian.org/benchmarksgame-team/benchmarksgame/

   Naive transliteration from Michael Ferguson's Chapel program
   contributed by Isaac Gouy   
*/

const PI = Math.PI;
const SOLAR_MASS = 4 * PI * PI;
const DAYS_PER_YEAR = 365.24;

class Body {
    constructor(x, y, z, vx, vy, vz, mass) {
        this.x = x;
        this.y = y;
        this.z = z;
        this.vx = vx;
        this.vy = vy;
        this.vz = vz;
        this.mass = mass;
    } 
}

function offsetMomentum(bodies) { 
    let px = py = pz = 0;
    for (const b of bodies) {
        px += b.vx * b.mass;
        py += b.vy * b.mass;
        pz += b.vz * b.mass;
    }
    const b = bodies[0];
    b.vx = -px / SOLAR_MASS;
    b.vy = -py / SOLAR_MASS;
    b.vz = -pz / SOLAR_MASS;
}

function energy(bodies) {
    let e = 0;
    const numBodies = bodies.length;
    for (let i = 0; i < numBodies; i++) {
        const b = bodies[i];
        const sq = b.vx * b.vx + b.vy * b.vy + b.vz * b.vz;    
        e += 0.5 * bodies[i].mass * sq;
        for (let j = i + 1; j < numBodies; j++) {
            const dx = b.x - bodies[j].x; 
            const dy = b.y - bodies[j].y; 
            const dz = b.z - bodies[j].z;   
            const sq = dx * dx + dy * dy + dz * dz;          
            e -= (b.mass * bodies[j].mass) / Math.sqrt(sq)        
        }
    }
    return e;
}

function advance(bodies, dt) {
    const numBodies = bodies.length;
    for (let i = 0; i < numBodies; i++) {
        for (let j = i + 1; j < numBodies; j++) {
            const dx = bodies[i].x - bodies[j].x; 
            const dy = bodies[i].y - bodies[j].y; 
            const dz = bodies[i].z - bodies[j].z;          
            const sq = dx * dx + dy * dy + dz * dz;
            const mag = dt / (sq * Math.sqrt(sq));            

            const mj = bodies[j].mass * mag;
            bodies[i].vx -= dx * mj;  
            bodies[i].vy -= dy * mj;   
            bodies[i].vz -= dz * mj;

            const mi = bodies[i].mass * mag;
            bodies[j].vx += dx * mi;  
            bodies[j].vy += dy * mi;   
            bodies[j].vz += dz * mi;
        }
    }
    for (const b of bodies) {    
        b.x += b.vx * dt;  
        b.y += b.vy * dt;   
        b.z += b.vz * dt;
    }
}

